package com.ecommerce.cart.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.concurrent.*; import java.util.concurrent.atomic.AtomicInteger;
@Component public class RateLimitFilter extends OncePerRequestFilter {static class W{long start=System.currentTimeMillis();AtomicInteger count=new AtomicInteger();}private final ConcurrentHashMap<String,W> map=new ConcurrentHashMap<>();private final int limit;private final long ms;public RateLimitFilter(@Value("${app.limit.requests:60}")int l,@Value("${app.limit.seconds:60}")int s){limit=Math.max(1,l);ms=Math.max(1,s)*1000L;}protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String k=r.getRemoteAddr()+":"+r.getRequestURI();long n=System.currentTimeMillis();W w=map.compute(k,(x,o)->o==null||n-o.start>=ms?new W():o);if(w.count.incrementAndGet()>limit){long retry=Math.max(1,(w.start+ms-n+999)/1000);s.setStatus(429);s.setHeader("Retry-After",Long.toString(retry));s.setContentType("application/json");s.getWriter().write("{\"error\":\"Rate limit exceeded\",\"retryAfterSeconds\":"+retry+"}");return;}c.doFilter(r,s);}}